import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const h=JSON.parse('{"title":"Web App Guide","description":"","frontmatter":{},"headers":[],"relativePath":"web-app.md","filePath":"web-app.md"}'),s={name:"web-app.md"};function n(i,e,l,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="web-app-guide" tabindex="-1">Web App Guide <a class="header-anchor" href="#web-app-guide" aria-label="Permalink to &quot;Web App Guide&quot;">​</a></h1><p>Sky Style combines live weather, your saved closet, and an AI recommendation in one dashboard.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ol><li>Create an account at <a href="https://skystyle.app" target="_blank" rel="noreferrer">skystyle.app</a>.</li><li>Choose a location manually or permit location access.</li><li>Add the clothes you actually own in <strong>Closet</strong>.</li><li>Generate a recommendation and use follow-up questions to refine it.</li></ol><h2 id="useful-account-tools" tabindex="-1">Useful account tools <a class="header-anchor" href="#useful-account-tools" aria-label="Permalink to &quot;Useful account tools&quot;">​</a></h2><ul><li><strong>Inbox</strong> keeps recommendation, support, system, and changelog notices together.</li><li><strong>Automatic recommendations</strong> store an exact scheduled weather/outfit result for later review.</li><li><strong>Settings</strong> controls appearance, layout, dashboard behaviour, spacing, and replayable tutorials.</li><li><strong>Account</strong> shows usage, security, privacy controls, and API access.</li></ul><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Sky Style keeps three balances distinct:</p><table tabindex="0"><thead><tr><th>Balance</th><th>Use</th></tr></thead><tbody><tr><td>$ Credit (AUD)</td><td>Convert $1.00 into 50 API Credit for a key you choose. Pro receives $1.00 each calendar month.</td></tr><tr><td>API Credit</td><td>Per-key balance consumed by public API requests.</td></tr><tr><td>App Credit</td><td>In-app balance, including developer gifts and API fallback when a key&#39;s API Credit is empty.</td></tr></tbody></table><p>API credit purchases are not live yet; the app&#39;s donation prompt is intentionally informational.</p><h2 id="help-and-service-status" tabindex="-1">Help and service status <a class="header-anchor" href="#help-and-service-status" aria-label="Permalink to &quot;Help and service status&quot;">​</a></h2><p>Use the app Inbox or Feedback page for account help. API users should consult the <a href="/api/errors.html">API error guide</a> and the project status page linked from the app.</p>',12)])])}const b=t(s,[["render",n]]);export{h as __pageData,b as default};
